<script setup>
import {ref, computed, onUnmounted} from 'vue';
import { ArrowUpRight, ArrowRight, UploadCloud, FileText, Film, Image, Sparkles, X, Check, Download, ArrowUp, ArrowDown, FolderOpen, ShieldCheck, Coffee, Menu, LoaderCircle, CircleHelp, Plus, WandSparkles } from '@lucide/vue';
const tools=[
 {id:'pdf',name:'PDF playground',short:'PDF',tag:'A little less paperwork.',description:'Bring pages together. Or give them some space.',icon:FileText,color:'peach',action:'Merge & separate',doodle:'pages'},
 {id:'video',name:'Video squeeze',short:'Video',tag:'Big moments. Smaller files.',description:'Keep the good stuff. Lose the extra megabytes.',icon:Film,color:'lavender',action:'Shrink a video',doodle:'video'},
 {id:'gif',name:'Actually a GIF',short:'GIF',tag:'Let it loop. For real.',description:'Turn those Twitter “GIFs” into the real thing.',icon:Sparkles,color:'yellow',action:'Make a GIF',doodle:'gif'},
 {id:'images',name:'Image squish',short:'Images',tag:'A lighter kind of picture.',description:'One photo or a whole folder. Less weight, more wow.',icon:Image,color:'mint',action:'Optimize images',doodle:'image'}
];
const selected=ref(null),current=computed(()=>tools.find(t=>t.id===selected.value)),files=ref([]),dragging=ref(false),error=ref(''),job=ref(null),busy=ref(false),uploadPercent=ref(0),uploading=ref(false),help=ref(false), mobile=ref(false);
const input=ref(),folder=ref();let timer, xhr, generation=0;
const settings=ref({mode:'merge',pages:'',target:8,width:1280,mute:false,format:'webp',quality:80,url:'',start:0,duration:10,fps:15,limit:true});
const accept=computed(()=>selected.value==='pdf'?'.pdf':selected.value==='images'?'.jpg,.jpeg,.png,.webp,.avif,.gif,.tif,.tiff,.svg,.heic,.heif,.bmp,.ico':'video/*,.mkv,.mov,.webm,.mp4');
const bytes=n=>n<1000000?`${(n/1000).toFixed(1)} KB`:`${(n/1000000).toFixed(2)} MB`;
const total=computed(()=>files.value.reduce((sum,f)=>sum+f.size,0));
function open(id){if(busy.value)return;selected.value=id;files.value=[];error.value='';job.value=null;settings.value={mode:'merge',pages:'',target:id==='gif'?5:8,width:id==='images'?2400:id==='gif'?640:1280,mute:false,format:'webp',quality:80,url:'',start:0,duration:10,fps:15,limit:true};mobile.value=false;setTimeout(()=>document.querySelector('#workbench')?.scrollIntoView({behavior:'smooth',block:'start'}),30);}
function add(list){if(busy.value)return;error.value='';job.value=null;const incoming=Array.from(list);if(files.value.length+incoming.length>200){error.value='Choose up to 200 files at a time.';return;}for(const f of incoming){if(f.size>1e9){error.value=`${f.name} is over the 1 GB file limit.`;continue;}if(!f.size){error.value=`${f.name} is empty and was skipped.`;continue;}if(!files.value.some(x=>x.name===f.name&&x.size===f.size&&x.lastModified===f.lastModified&&x.webkitRelativePath===f.webkitRelativePath))files.value.push(f);}if(input.value)input.value.value='';if(folder.value)folder.value.value='';}
function drop(e){dragging.value=false;add(e.dataTransfer.files);}
function move(i,d){const a=files.value.splice(i,1)[0];files.value.splice(i+d,0,a);}
async function poll(id,token){if(token!==generation)return;try{const r=await fetch(`/api/jobs/${id}`);const data=await r.json();if(token!==generation)return;if(!r.ok)throw Error(data.error);error.value='';job.value=data;if(['done','error','cancelled'].includes(data.status)){busy.value=false;return;}timer=setTimeout(()=>poll(id,token),1000);}catch(e){if(token!==generation)return;error.value='Connection lost. Retrying…';timer=setTimeout(()=>poll(id,token),3000);}}
async function submit(){error.value='';job.value=null;if(!files.value.length&&!(selected.value==='gif'&&settings.value.url.trim())){error.value='Add a file to get started.';return;}if(['video','gif'].includes(selected.value)&&files.value.length>1){error.value='Choose one video at a time.';return;}if(selected.value==='pdf'&&settings.value.mode!=='merge'&&files.value.length!==1){error.value='Select a single PDF to separate its pages.';return;}
 busy.value=true;uploading.value=true;uploadPercent.value=0;const token=++generation;const form=new FormData();form.append('tool',selected.value);Object.entries(settings.value).forEach(([k,v])=>form.append(k,String(v)));files.value.forEach(f=>form.append('files',f,f.name));
 xhr=new XMLHttpRequest();xhr.open('POST','/api/jobs');xhr.upload.onprogress=e=>{if(e.lengthComputable)uploadPercent.value=Math.round(e.loaded/e.total*100);};xhr.onload=()=>{uploading.value=false;if(token!==generation)return;try{const data=JSON.parse(xhr.responseText);if(xhr.status!==200)throw Error(data.error||'Upload failed.');job.value={id:data.id,status:'queued',message:'Getting the workbench ready…',progress:0,results:[],warnings:[]};poll(data.id,token);}catch(e){error.value=e.message;busy.value=false;}};xhr.onerror=()=>{uploading.value=false;busy.value=false;error.value='Cannot reach the processing server. Please try again shortly.';};xhr.send(form);
}
async function cancel(){generation++;clearTimeout(timer);xhr?.abort();if(job.value?.id)await fetch(`/api/jobs/${job.value.id}`,{method:'DELETE'}).catch(()=>{});busy.value=false;uploading.value=false;job.value=null;error.value='Processing cancelled.';}
onUnmounted(()=>{clearTimeout(timer);xhr?.abort();});
</script>

<template>
 <div class="page-shell">
  <header class="header"><a href="#" class="brand" @click.prevent="!busy&&(selected=null)"><span class="brand-icon"><WandSparkles :size="24"/></span>doodle<span class="brand-light">tools</span><span class="brand-dot">&#10035;</span></a><nav :class="{show:mobile}"><a href="#tools" @click="mobile=false">The toolbox <span>&#8599;</span></a><button @click="help=!help">How it works <CircleHelp :size="15"/></button></nav><span class="local-badge"><span></span> Made for your everyday</span><button class="mobile-menu" aria-label="Toggle menu" @click="mobile=!mobile"><Menu/></button></header>
  <main>
   <section class="hero">
    <div class="hero-star" aria-hidden="true">&#10035;</div><div class="eyebrow"><span class="tiny-star">&#10022;</span> LITTLE TOOLS. BIG EXHALE.</div>
    <h1>Your files.<br>A little <span class="magic-word">lighter.<svg viewBox="0 0 400 25" preserveAspectRatio="none"><path d="M4 12 Q160 -2 395 9 M20 22 Q200 7 370 18"/></svg></span><span class="hero-spark" aria-hidden="true">&#10023;</span></h1>
    <p>A happy little home for the file jobs you keep putting off.<br class="desktop-br"> Merge, shrink, convert. Get on with your day.</p>
    <div class="hero-bottom"><a class="button ink" href="#tools">Find your tool <ArrowRight :size="18"/></a><span class="hand-note">no sign-ups, no fuss.<svg viewBox="0 0 60 35"><path d="M55 3Q30 35 3 19m0 0 12-5M3 19l8 9"/></svg></span></div>
    <svg class="hero-art" viewBox="0 0 220 230" fill="none" aria-hidden="true"><path d="M43 70Q35 38 65 39l91 6 16 113-123 7z" fill="#dfebdd"/><path d="m71 21 91 5 26 32-9 125-124-7 8-146q0-9 8-10Z" fill="#fffdf7"/><path d="m162 26-3 36 29-4M80 85l66 3M78 101l66 3M76 117l43 3"/><path d="m111 157 10 10 23-29" stroke="#648464"/><path d="m21 95-8-7m8 22-13 2m182-99 4-10m8 25 12-3"/><path d="m149 207 18-41 15 18 22 6-55 17Z" fill="#f8cd87"/><path d="m149 207 33-23 3 17M167 166l15 18"/><path d="m32 189 4-10 6 9 10 1-8 7 1 11-10-6-10 3 4-10-7-6z" fill="#ddd0ee"/><path d="M12 152q-10 18 9 16t8-19" stroke-dasharray="3 6"/></svg>
   </section>
   <section id="tools" class="toolbox"><div class="section-top"><div><span class="eyebrow">THE TOOLBOX</span><h2>What are we fixing today?<span class="small-spark">&#10023;</span></h2></div><span class="hand-note count-note">four tools. endless possibilities.</span></div>
    <div class="cards"><button v-for="(t,i) in tools" :key="t.id" :class="['tool-card',t.color,{chosen:selected===t.id}]" @click="open(t.id)" :disabled="busy" :aria-pressed="selected===t.id"><div class="card-top"><span class="tool-number">0{{i+1}}</span><ArrowUpRight class="card-arrow" :size="22"/></div><div class="card-doodle" aria-hidden="true"><svg v-if="t.id==='pdf'" viewBox="0 0 130 100"><path d="m30 16 51-4 18 18 4 57-69 6z" fill="#fffaf2"/><path d="m81 12 2 21 16-3M46 47l36-3M47 59l30-3M46 71l23-2M21 26l-8 4 8 62 66-3 1-6"/><path d="m94 63 17 1m-5-6 6 6-6 7"/></svg><svg v-else-if="t.id==='video'" viewBox="0 0 130 100"><rect x="23" y="17" width="84" height="65" rx="8" fill="#fffaf2" transform="rotate(-5 65 50)"/><path d="m53 35 1 31 26-17z" fill="#c4b2da"/><path d="m18 3-2 10m-11 3 9 5m95 63 7 6m-10 0 2 9M25 29l80-6M28 72l80-6"/></svg><svg v-else-if="t.id==='gif'" viewBox="0 0 130 100"><path d="M96 24Q50-9 28 29L19 44m0 0-2-21m2 21 22-4M33 77q49 31 72-11l8-13m0 0-22 5m22-5 1 23"/><path d="m55 29 28 20-28 21Z" fill="#fffaf2"/><path d="m100 9 2-8m8 15 9-3M16 79l-8 6"/></svg><svg v-else viewBox="0 0 130 100"><rect x="19" y="18" width="87" height="67" rx="5" fill="#fffaf2" transform="rotate(5 60 50)"/><path d="m24 74 27-28 19 21 12-14 19 26" fill="#aec9ab"/><circle cx="83" cy="37" r="8" fill="#f2cf83"/><path d="m14 8-3 8m103 70 10 5m-11-70 9-4"/></svg></div><span class="card-tag">{{t.tag}}</span><h3>{{t.name}}</h3><p>{{t.description}}</p><span class="card-action">{{t.action}} <ArrowRight :size="17"/></span></button></div>
   </section>
   <section v-if="selected" id="workbench" class="workbench" :class="current.color">
    <div class="bench-heading"><div><span class="eyebrow">YOUR WORKBENCH / {{current.short.toUpperCase()}}</span><h2><component :is="current.icon" :size="27"/> {{current.name}}</h2></div><button class="icon-btn" :disabled="busy" @click="selected=null" aria-label="Close tool"><X/></button></div>
    <form @submit.prevent="submit"><fieldset :disabled="busy">
     <div v-if="selected==='pdf'" class="segmented"><label v-for="[value,label] in [['merge','Merge PDFs'],['extract','Extract pages'],['each','Separate pages']]" :class="{active:settings.mode===value}"><input type="radio" v-model="settings.mode" :value="value">{{label}}</label></div>
     <div v-if="selected==='gif'" class="url-input"><label for="tweet">Twitter / X post link <span class="muted">(or upload an MP4 below)</span></label><input id="tweet" v-model="settings.url" type="url" placeholder="https://x.com/username/status/…" :disabled="files.length>0"><p class="hint">Public posts only. If X blocks access, save the MP4 and upload it here.</p></div>
     <div class="dropzone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop"><span class="upload-icon"><UploadCloud :size="31"/></span><h3>Drop {{selected==='pdf'?'your PDFs':selected==='images'?'your images':'your video'}} right here</h3><p>or pick them the old-fashioned way</p><div class="browse-actions"><button type="button" class="button small" @click="input.click()"><Plus :size="16"/> Choose files</button><button v-if="selected==='images'" type="button" class="button small" @click="folder.click()"><FolderOpen :size="16"/> Choose folder</button></div><span class="hint">{{selected==='images'?'JPG, PNG, WebP, AVIF, TIFF, SVG & more · up to 200 files':selected==='pdf'?'PDF documents · up to 200 files':'MP4, MOV, WebM, MKV & more · one video at a time'}} · 1 GB per file</span><input ref="input" type="file" hidden :accept="accept" :multiple="selected==='images'||selected==='pdf'" @change="add($event.target.files)"><input ref="folder" type="file" hidden multiple webkitdirectory @change="add($event.target.files)"></div>
     <div v-if="files.length" class="file-list"><div class="file-summary">{{files.length}} file{{files.length===1?'':'s'}} · {{bytes(total)}}<button type="button" @click="files=[]">Clear all</button></div><div v-for="(f,i) in files" :key="`${f.name}-${i}`" class="file-row"><FileText :size="18"/><span class="filename">{{f.webkitRelativePath||f.name}}</span><span class="muted">{{bytes(f.size)}}</span><template v-if="selected==='pdf'&&settings.mode==='merge'"><button type="button" :disabled="i===0" @click="move(i,-1)" aria-label="Move PDF up"><ArrowUp :size="16"/></button><button type="button" :disabled="i===files.length-1" @click="move(i,1)" aria-label="Move PDF down"><ArrowDown :size="16"/></button></template><button type="button" @click="files.splice(i,1)" aria-label="Remove file"><X :size="16"/></button></div></div>
     <div class="settings-grid">
      <template v-if="selected==='pdf'"><label v-if="settings.mode!=='merge'">Pages to include<input v-model="settings.pages" placeholder="All pages, or e.g. 1-3, 5, 8-10"><span class="hint">Page numbers start at 1. Order and repeats are preserved.</span></label><p class="hint settings-note">{{settings.mode==='merge'?'PDFs are merged in the order above. Use the arrows to rearrange them.':'Extract returns one PDF. Separate returns a PDF for each selected page.'}} Password-protected documents must be unlocked first. Interactive forms, signatures and bookmarks may not survive copying.</p></template>
      <template v-if="selected==='video'"><label>Maximum file size<div class="presets"><button v-for="n in [8,20,50]" type="button" @click="settings.target=n" :class="{active:settings.target===n}">{{n}} MB</button></div><div class="with-unit"><input v-model="settings.target" type="number" min="0.1" max="1000" step="0.1" required><span>MB</span></div></label><label>Maximum video width<select v-model="settings.width"><option :value="1920">1920 px · Full HD</option><option :value="1280">1280 px · Balanced</option><option :value="854">854 px · Smaller</option><option :value="480">480 px · Compact</option></select><span class="hint">Resolution adapts to the size budget. MP4 / H.264 output.</span></label><label class="checkbox"><input v-model="settings.mute" type="checkbox"> Remove audio for a smaller file</label></template>
      <template v-if="selected==='gif'"><label>Start time (seconds)<input v-model="settings.start" type="number" min="0" step="0.1" required></label><label>Duration (seconds)<input v-model="settings.duration" type="number" min="0.1" max="60" step="0.1" required></label><label>Width (pixels)<input v-model="settings.width" type="number" min="80" max="1280" required></label><label>Frames per second<select v-model="settings.fps"><option :value="10">10 · Smaller</option><option :value="15">15 · Balanced</option><option :value="24">24 · Smoother</option><option :value="30">30 · Smoothest</option></select></label><label class="checkbox"><input v-model="settings.limit" type="checkbox"> Keep the GIF under a size limit</label><label v-if="settings.limit">Maximum size (MB)<input v-model="settings.target" type="number" min="0.1" max="100" step="0.1" required><span class="hint">Starts at your chosen quality; lowers width and frame rate only if needed.</span></label><p class="hint">GIFs loop forever and have no audio. Clips are capped at 60 seconds.</p></template>
      <template v-if="selected==='images'"><label>Output format<select v-model="settings.format"><option value="webp">WebP · Great all-rounder</option><option value="avif">AVIF · Smaller, slower to encode</option><option value="jpeg">JPEG · Widely compatible</option><option value="png">PNG · Optimized palette</option></select></label><label>Maximum width (pixels)<input v-model="settings.width" type="number" min="16" max="16000" required><span class="hint">Keeps proportions. Never enlarges.</span></label><label>Quality <span class="quality-value">{{settings.quality}}%</span><input v-model="settings.quality" type="range" min="1" max="100"><span class="hint">Lower = smaller. Higher = more detail.</span></label><p class="hint settings-note">Orientation is corrected and metadata removed. JPEG uses a white background for transparency. Animated/multipage files are skipped. HEIC/RAW support depends on the decoder; unsupported files get an individual error.</p></template>
     </div>
    </fieldset><div v-if="error" class="alert" role="alert">{{error}}</div><div class="bench-footer"><span><ShieldCheck :size="17"/> Processed on this app's server. Files expire after 1 hour.</span><button v-if="!busy" class="button ink" type="submit"><WandSparkles :size="18"/> {{selected==='pdf'?'Work some PDF magic':selected==='video'?'Squeeze my video':selected==='gif'?'Make it a GIF':'Squish my images'}}</button><button v-else class="button" type="button" @click="cancel"><X :size="17"/> Cancel</button></div></form>
    <div v-if="busy" class="progress-panel" role="status" aria-live="polite"><LoaderCircle class="spin" :size="22"/><div><strong>{{uploading?`Uploading · ${uploadPercent}%`:job?.message}}</strong><div class="progress-track"><span :style="{width:`${uploading?uploadPercent:job?.progress||4}%`}"></span></div><p class="hint">Good things take a little processing. Keep this tab open.</p></div></div>
    <div v-if="job?.status==='error'" class="alert" role="alert">{{job.message}}</div>
    <div v-if="job?.status==='done'" class="results"><div class="results-heading"><h3><Check :size="22"/> A little lighter. All yours.</h3><a class="button small" :href="`/api/jobs/${job.id}/zip`"><Download :size="16"/> Download ZIP</a></div><div v-for="r in job.results" :key="r.id" class="result-row"><FileText :size="19"/><div><strong>{{r.name}}</strong><span>{{bytes(r.size)}} <template v-if="r.original">· {{r.size<r.original?`${Math.round((1-r.size/r.original)*100)}% smaller`:'Converted · output is larger than original'}}</template></span></div><a :href="`/api/jobs/${job.id}/files/${r.id}`" :aria-label="`Download ${r.name}`"><Download :size="20"/></a></div></div>
    <div v-if="job?.warnings?.length" class="warnings"><strong>A few files need attention</strong><p v-for="w in job.warnings">{{w}}</p></div>
   </section>
   <section class="why"><div class="why-title"><span class="scribble-heart">&#9825;</span><div><h2>Small tools.<br>Thoughtfully made.</h2><p>Just the useful stuff. With a little personality.</p></div></div><div class="why-item"><ShieldCheck :size="25"/><h3>Your files, your business.</h3><p>Temporary file processing.<br>No account. Files expire.</p></div><div class="why-item"><WandSparkles :size="25"/><h3>Less fiddling. More doing.</h3><p>Sensible defaults. Extra control<br>when you want it.</p></div></section>
   <section v-if="help" class="help-panel"><h2>A quick note from the workbench</h2><p>Choose a tool, add your files, adjust the settings, and press the magic button. Download files individually or together as a ZIP. Files are uploaded to the server running this app and expire one hour after processing. When running locally, that server is your own computer. A server restart clears the job list.</p><p>MB means 1,000,000 bytes. Video limits are verified after encoding; extremely small targets may be impossible. Image conversion can sometimes increase size. PDFs are copied without rasterizing their pages. Public Twitter links require yt-dlp and may be blocked by X; uploading an MP4 always provides a fallback.</p><button class="button small" @click="help=false">Got it <Check :size="16"/></button></section>
   <div class="coming-note"><span class="tiny-star">&#10022;</span> A growing collection of little lifesavers. <span class="hand-note">more on the way!</span></div>
  </main>
  <footer><a href="#" class="brand small-brand">doodle<span class="brand-light">tools</span><span class="brand-dot">&#10035;</span></a><span>Made with a little care & a lot of coffee. <Coffee :size="15"/></span><button @click="help=!help">The small print <ArrowUpRight :size="14"/></button></footer>
 </div>
</template>



